@import url('https://fonts.googleapis.com/css2?family=DM+Mono:wght@400;500&family=DM+Sans:wght@400;500;600;700&family=Space+Grotesk:wght@400;500;600;700&display=swap');
:root{color-scheme:dark;--bg:#090b10;--panel:#11141c;--panel2:#151923;--line:#252a35;--muted:#7b8292;--text:#f4f5f8;--cyan:#54e3dc;--pink:#ff4e97;--green:#92f35d;--mono:'DM Mono',monospace;--sans:'DM Sans',sans-serif;--display:'Space Grotesk',sans-serif}
*{box-sizing:border-box}body{margin:0;background:radial-gradient(ellipse at 50% -30%,#202638 0,transparent 55%),var(--bg);color:var(--text);font:14px var(--sans);min-width:320px}.app-shell{max-width:1440px;margin:auto;padding:0 42px}.topbar{height:76px;border-bottom:1px solid #ffffff0e;display:flex;align-items:center;justify-content:space-between}.brand{display:flex;gap:10px;align-items:center;text-decoration:none;color:var(--text);font:700 16px var(--display);letter-spacing:-.6px}.brand-mark{display:grid;place-items:center;width:34px;height:34px;border:1px solid #54e3dc66;border-radius:11px;color:var(--cyan);font-size:20px;box-shadow:0 0 22px #54e3dc1a}.brand-accent{color:var(--cyan)}.brand small{display:block;color:#777e8d;font:8px var(--mono);letter-spacing:1.55px;margin-top:1px}.session-pill{display:flex;gap:9px;align-items:center;border:1px solid var(--line);border-radius:20px;padding:7px 12px;color:#a9afbd;font:9px var(--mono);letter-spacing:.7px}.live-dot,.deck-led{width:7px;height:7px;border-radius:50%;background:#76e3a8;box-shadow:0 0 8px #76e3a8}.top-actions{display:flex;align-items:center;gap:20px}.quiet-button{background:#12151d;border:1px solid #2a2f3c;color:#b9bfca;padding:9px 13px;border-radius:7px;font:10px var(--mono);letter-spacing:.55px;cursor:pointer}.quiet-button:hover{border-color:#555d6e;color:white}.quiet-button span{color:var(--cyan)}.avatar{width:32px;height:32px;border-radius:50%;background:#232838;border:1px solid #41495c;color:#bbc4d7;font:11px var(--mono)}main{padding-bottom:44px}.intro-row{display:flex;justify-content:space-between;align-items:end;padding:37px 0 24px}.eyebrow{font:9px var(--mono);letter-spacing:1.45px;color:#8a91a1;margin:0 0 10px}.eyebrow span{color:var(--pink);padding:0 4px}h1,h2,p{margin-top:0}h1{font:600 clamp(28px,4vw,39px) var(--display);letter-spacing:-1.6px;margin:0 0 7px}h1 em,.library-heading h2 em{font-style:normal;color:var(--cyan)}.intro-copy{color:#858c9c;margin:0;font-size:13px}.lesson-progress{display:grid;grid-template-columns:130px 82px 35px;gap:9px;align-items:center;color:#8c93a2;font:9px var(--mono);letter-spacing:.5px;padding-bottom:5px}.lesson-progress b{text-align:right;color:var(--cyan);font-weight:400}.progress-track{height:3px;background:#282c36}.progress-track i{display:block;width:25%;height:100%;background:var(--cyan);box-shadow:0 0 8px #54e3dc7a}.wave-stack{border:1px solid #262b36;border-radius:10px;background:#0d1017;padding:12px 16px 10px;margin-bottom:16px;box-shadow:0 12px 35px #0003}.wave-label{height:21px;display:flex;align-items:center;gap:8px;color:#dfe3eb;font:9px var(--mono);letter-spacing:1px}.wave-label small{font-size:8px;color:#747b89;letter-spacing:.6px}.channel-dot{width:6px;height:6px;border-radius:50%;background:var(--cyan)}.wave-b .channel-dot{background:var(--pink)}.wave-time{margin-left:auto;color:#9299a8}.wave-stack canvas{width:100%;height:67px;display:block}.wave-divider{height:22px;border-top:1px solid #212631;border-bottom:1px solid #212631;display:flex;align-items:center;justify-content:center;gap:18px;color:#777e8b;font:8px var(--mono);letter-spacing:1px}.beat-lights{display:flex;gap:4px}.beat-lights i{width:4px;height:4px;border-radius:50%;background:#3e4451}.beat-lights i:first-child{background:var(--cyan)}.mixer-layout{display:grid;grid-template-columns:minmax(0,1fr) 230px minmax(0,1fr);gap:12px;align-items:stretch}.deck{border:1px solid #282d38;background:linear-gradient(145deg,#141821,#10131a);border-radius:10px;padding:15px 16px 14px;min-width:0}.deck-a{--deck:var(--cyan)}.deck-b{--deck:var(--pink)}.deck-heading{display:flex;align-items:center;gap:10px;padding-bottom:13px;border-bottom:1px solid #252a35}.deck-index{display:grid;place-items:center;width:28px;height:28px;border-radius:7px;background:color-mix(in srgb,var(--deck) 13%,transparent);color:var(--deck);font:500 14px var(--mono)}.deck-heading h2{font:600 12px var(--display);letter-spacing:1px;margin:0}.deck-heading p{font:8px var(--mono);letter-spacing:1px;color:#777e8d;margin:3px 0 0}.deck-heading .deck-led{margin-left:auto;background:var(--deck);box-shadow:0 0 8px var(--deck)}.track-card{display:flex;align-items:center;gap:10px;padding:13px 0 9px}.record-art{flex:0 0 43px;height:43px;border-radius:7px;display:grid;place-items:center;font-size:21px}.art-a{background:radial-gradient(circle,#111a20 0 18%,#51dcd3 19% 23%,#13252a 24% 40%,#52e3dc44 41% 100%);color:#64e7df}.art-b{background:radial-gradient(circle,#1e131b 0 18%,#fa4a94 19% 23%,#2d1824 24% 40%,#ff4e9744 41% 100%);color:#ff64a5}.track-info{display:grid;gap:4px;min-width:0;flex:1}.track-info strong{font:500 11px var(--display);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.track-info span{font:9px var(--sans);color:#838b9a;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.icon-button{background:transparent;border:1px solid #3b414e;border-radius:5px;color:#929aa9;font:9px var(--mono);padding:7px 8px;cursor:pointer}.icon-button:hover{border-color:var(--deck);color:var(--deck)}.tempo-row{height:32px;display:flex;align-items:center;gap:9px;border-top:1px solid #252a35;border-bottom:1px solid #252a35;font:8px var(--mono);color:#818897;letter-spacing:.7px}.tempo-row strong{font:500 14px var(--mono);color:#f5f6f8;letter-spacing:0}.key-chip{padding:3px 5px;border:1px solid #333a47;border-radius:3px;color:#bac2ce}.tempo-change{margin-left:auto;color:var(--deck)}.transport-row{display:flex;align-items:center;gap:6px;padding:11px 0}.transport{height:29px;min-width:34px;border:0;border-radius:5px;background:var(--deck);color:#10131a;font-size:12px;cursor:pointer}.transport.is-playing{box-shadow:0 0 12px color-mix(in srgb,var(--deck) 65%,transparent)}.transport.secondary{background:#222733;color:#c0c6d1;font:8px var(--mono);padding:0 8px}.demo-button,.load-button{border:1px solid #303642;background:#191d26;color:#b9c1cd;border-radius:5px;padding:7px 8px;font:8px var(--mono);cursor:pointer;white-space:nowrap}.demo-button:hover,.load-button:hover{border-color:var(--deck);color:var(--deck)}.load-button{margin-left:auto;position:relative}.load-button input{position:absolute;width:1px;height:1px;opacity:0;pointer-events:none}.deck-controls{display:grid;grid-template-columns:minmax(0,1fr) 65px;gap:10px;border-top:1px solid #252a35;padding-top:11px}.control-title{font:8px var(--mono);letter-spacing:1px;color:#7e8695;margin-bottom:9px}.knob-row{display:flex;justify-content:space-between;gap:7px}.knob-control{display:flex;flex-direction:column;align-items:center;gap:5px;position:relative;cursor:ns-resize}.knob-control input{position:absolute;width:35px;height:35px;opacity:0;z-index:2;cursor:ns-resize}.knob{height:33px;width:33px;border-radius:50%;background:linear-gradient(145deg,#303641,#12151b);border:1px solid #414754;box-shadow:3px 4px 8px #0008,inset 0 1px 2px #ffffff18;display:grid;place-items:center;transform:rotate(var(--rotation,0deg))}.knob i{width:2px;height:8px;background:var(--deck);border-radius:2px;align-self:start;margin-top:4px;box-shadow:0 0 5px var(--deck)}.knob-control b{font:8px var(--mono);letter-spacing:.4px;color:#a4aab5}.knob-control small{font:7px var(--mono);color:#7d8492}.slider-block{display:flex;gap:12px}.slider-block label{font:7px var(--mono);letter-spacing:.3px;color:#8d94a1;display:grid;gap:7px;justify-items:center;align-content:start}.slider-block label small{font:8px var(--mono);color:var(--deck)}input[type=range]{accent-color:var(--deck);cursor:pointer}.slider-block input{writing-mode:vertical-lr;direction:rtl;appearance:slider-vertical;height:77px;width:16px;margin:0;accent-color:var(--deck)}.center-mixer{border:1px solid #292e3a;background:linear-gradient(155deg,#171b26,#10131a);border-radius:10px;padding:13px 13px 11px;display:flex;flex-direction:column}.mixer-top{height:26px;display:flex;align-items:center;justify-content:space-between;color:#8e96a4;font:8px var(--mono);letter-spacing:1px}.mixer-top strong{font:10px var(--mono);color:#dce1ea}.mixer-top strong small{font-size:7px;color:#858d9a}.master-meter{display:flex;gap:3px}.master-meter i{width:7px;height:13px;border-radius:2px;background:#26313a}.master-meter i:nth-child(1),.master-meter i:nth-child(2){background:#58d4bd}.master-meter i:nth-child(3),.master-meter i:nth-child(4){background:#9be461}.master-meter i:nth-child(n+5){background:#5b3445}.lesson-card{display:flex;align-items:center;gap:9px;border:1px solid #34313e;background:linear-gradient(100deg,#262334,#191a25);border-radius:7px;padding:11px 8px;margin:5px 0 10px}.lesson-icon{width:28px;height:28px;border-radius:7px;background:#392c46;color:#d98df3;display:grid;place-items:center;font-size:17px}.lesson-copy{flex:1;min-width:0}.lesson-copy .eyebrow{font-size:7px;color:#c38cd5;margin-bottom:3px}.lesson-copy strong{font:600 10px var(--display)}.lesson-copy p{font-size:8px;line-height:1.4;color:#a0a5b0;margin:3px 0 0}.lesson-copy p b{color:#f5b1ff}.lesson-level{font:10px var(--mono);color:#9e82b0;align-self:flex-start}.score-card{display:flex;align-items:center;gap:8px;padding:9px;border-radius:6px;background:#141a1d;border:1px solid #26373a;min-height:48px}.score-icon{color:var(--cyan);font-size:17px}.score-card>div{display:grid;gap:3px;flex:1}.score-card strong{font:8px var(--mono);letter-spacing:.4px;color:var(--cyan)}.score-card small{font:8px var(--sans);color:#87909d}.score-value{font:11px var(--mono);color:#e4e9ec}.score-card.good{border-color:#526438;background:#1a2118}.score-card.good .score-icon,.score-card.good strong{color:var(--green)}.score-card.bad{border-color:#58313b;background:#24171c}.score-card.bad .score-icon,.score-card.bad strong{color:#ff6b7b}.crossfader-block{margin-top:auto;padding-top:14px}.cross-label{display:flex;align-items:center;justify-content:space-between;font:8px var(--mono);color:#8e95a3}.cross-label b{letter-spacing:1px;color:#c4c9d2;font-size:8px}.crossfader-block input{width:100%;margin:12px 0 4px;accent-color:#c3a0ef}.cross-markers{display:flex;justify-content:space-between;align-items:center;color:#686f7e;font:8px var(--mono)}.cross-markers i{width:2px;height:4px;background:#424856}.check-button{width:100%;margin-top:12px;border:0;border-radius:5px;background:linear-gradient(90deg,#57dfd5,#8ee9a7);height:34px;display:flex;align-items:center;justify-content:space-between;padding:0 11px;color:#0b1417;font:700 8px var(--mono);letter-spacing:.7px;cursor:pointer}.check-button:hover{filter:brightness(1.1)}.check-button span:last-child{font-size:14px}.privacy-note{text-align:center;color:#636b78;font:7px var(--mono);margin:8px 0 0}.library-section{margin-top:28px}.library-heading{display:flex;align-items:end;justify-content:space-between;margin-bottom:12px}.library-heading h2{font:600 20px var(--display);letter-spacing:-.5px;margin:0}.library-heading .eyebrow{margin-bottom:5px}.library-actions{display:flex;align-items:center;gap:14px;color:#858d9b;font:8px var(--mono)}.library-actions .quiet-button{padding:8px 10px;font-size:8px}.library-table-wrap{border:1px solid #292e39;border-radius:8px;overflow:hidden;background:#10131a}table{width:100%;border-collapse:collapse;text-align:left}thead{background:#151922}th{height:33px;padding:0 14px;color:#777f8d;font:8px var(--mono);letter-spacing:.8px}td{padding:10px 14px;border-top:1px solid #242934;font-size:10px;color:#adb4c1}.empty-row td{height:95px;text-align:center}.empty-row td span,.empty-row td strong,.empty-row td small{display:block}.empty-row td span{font-size:18px;color:#626e7e;margin-bottom:4px}.empty-row td strong{font:500 10px var(--display);color:#b9c0cb}.empty-row td small{font-size:9px;color:#777f8d;margin-top:3px}.library-track{display:flex;align-items:center;gap:8px}.library-track i{width:24px;height:24px;border-radius:5px;background:#232a35;color:var(--cyan);display:grid;place-items:center;font-style:normal}.library-track span{display:grid;gap:3px}.library-track small{font-size:8px;color:#78808f}.table-load{background:transparent;border:1px solid #353d49;border-radius:4px;padding:5px 8px;color:#b9c2ce;font:8px var(--mono);cursor:pointer}.table-load:hover{border-color:var(--cyan);color:var(--cyan)}.library-footnote{font:8px var(--mono);color:#737b89;margin:9px 0 0}.library-footnote span{color:var(--cyan);padding-right:5px}footer{height:48px;border-top:1px solid #ffffff0e;display:flex;align-items:center;justify-content:space-between;color:#5e6572;font:8px var(--mono);letter-spacing:.8px}footer i{color:var(--cyan);font-style:normal;padding:0 4px}.toast{position:fixed;bottom:20px;left:50%;transform:translate(-50%,20px);padding:10px 15px;border:1px solid #35404b;border-radius:6px;background:#171d25;color:#e3e8f0;font:10px var(--mono);box-shadow:0 8px 30px #0008;opacity:0;pointer-events:none;transition:.2s;z-index:9}.toast.visible{opacity:1;transform:translate(-50%,0)}
@media(max-width:1050px){.app-shell{padding:0 24px}.mixer-layout{grid-template-columns:minmax(0,1fr) 205px minmax(0,1fr);gap:8px}.deck{padding:12px 11px}.deck-controls{grid-template-columns:minmax(0,1fr) 55px;gap:5px}.slider-block{gap:7px}.demo-button{padding:7px 5px}.center-mixer{padding:11px 9px}}
@media(max-width:760px){.app-shell{padding:0 14px}.topbar{height:62px}.session-pill{display:none}.intro-row{padding:27px 0 18px;align-items:start;gap:15px;flex-direction:column}.lesson-progress{grid-template-columns:120px 1fr 30px;width:100%}.wave-stack{padding:10px}.wave-stack canvas{height:56px}.mixer-layout{grid-template-columns:1fr 1fr}.center-mixer{grid-column:1/-1;grid-row:2}.deck-controls{grid-template-columns:1fr 54px}.deck-heading{padding-bottom:9px}.track-card{gap:7px}.record-art{height:35px;flex-basis:35px}.track-info strong{font-size:10px}.tempo-row{gap:6px}.transport-row{gap:4px}.demo-button,.load-button{font-size:7px;padding:7px 5px}.transport.secondary{padding:0 5px}.library-section{margin-top:22px}.library-heading h2{font-size:18px}th,td{padding-left:8px;padding-right:8px}th{font-size:7px}.library-footnote{line-height:1.5}.center-mixer{min-height:285px}}
@media(max-width:430px){.top-actions{gap:8px}.quiet-button{padding:8px;font-size:8px}.deck{padding:10px 8px}.deck-index{width:24px;height:24px}.deck-heading h2{font-size:10px}.deck-heading p{font-size:7px}.track-card{flex-wrap:wrap}.cue-button{padding:6px}.tempo-row{font-size:7px}.tempo-row strong{font-size:12px}.tempo-change{font-size:7px}.transport-row{flex-wrap:wrap}.demo-button{flex:1}.load-button{margin-left:0;flex:1;text-align:center}.deck-controls{grid-template-columns:1fr}.slider-block{justify-content:space-around;border-top:1px solid #252a35;padding-top:8px}.slider-block input{height:60px}.knob{width:29px;height:29px}.knob-control input{width:31px;height:31px}.library-actions{gap:6px}.library-actions .quiet-button{padding:7px 6px}.library-table-wrap{overflow-x:auto}table{min-width:540px}footer{font-size:7px}}

(() => {
  'use strict';

  const $ = (selector, root = document) => root.querySelector(selector);
  const $$ = (selector, root = document) => [...root.querySelectorAll(selector)];
  const STORAGE_KEY = 'djlab-library-v1';
  const TARGET_BPM = 120;
  const decks = {};
  let audioContext;
  let crossPosition = 0.5;
  let toastTimer;
  let midiAccess;
  const library = loadSavedLibrary();

  function loadSavedLibrary() {
    try {
      const value = JSON.parse(localStorage.getItem(STORAGE_KEY) || '[]');
      return Array.isArray(value) ? value.filter(item => item && typeof item.name === 'string').slice(0, 100) : [];
    } catch { return []; }
  }

  function persistLibrary() {
    try {
      const compact = library.map(({ id, name, bpm, duration, source, kind }) => ({ id, name, bpm, duration, source, kind }));
      localStorage.setItem(STORAGE_KEY, JSON.stringify(compact));
    } catch { toast('No se pudo guardar la biblioteca en este navegador.'); }
  }

  function ensureAudio() {
    if (!audioContext) {
      const Context = window.AudioContext || window.webkitAudioContext;
      if (!Context) throw new Error('Este navegador no tiene Web Audio API.');
      audioContext = new Context({ latencyHint: 'interactive' });
      for (const id of ['a', 'b']) createDeck(id);
    }
    if (audioContext.state === 'suspended') audioContext.resume();
    return audioContext;
  }

  function createDeck(id) {
    const audio = $(`#audio-${id}`);
    const source = audioContext.createMediaElementSource(audio);
    const low = audioContext.createBiquadFilter();
    const mid = audioContext.createBiquadFilter();
    const high = audioContext.createBiquadFilter();
    low.type = 'lowshelf'; low.frequency.value = 100;
    mid.type = 'peaking'; mid.frequency.value = 2500; mid.Q.value = 0.8;
    high.type = 'highshelf'; high.frequency.value = 12000;
    const volume = audioContext.createGain();
    const cross = audioContext.createGain();
    const analyser = audioContext.createAnalyser();
    analyser.fftSize = 1024;
    analyser.smoothingTimeConstant = 0.82;
    source.connect(low).connect(mid).connect(high).connect(volume).connect(cross).connect(analyser).connect(audioContext.destination);
    decks[id] = {
      id, audio, source, filters: { low, mid, high }, volume, cross, analyser,
      data: new Uint8Array(analyser.frequencyBinCount), bpm: id === 'a' ? 120 : 124,
      baseBpm: id === 'a' ? 120 : 124, pitch: 0, objectUrl: null, trackName: '', artist: '',
      demo: false, cuePoint: 0, lastPhase: 0
    };
  }

  function setCrossfader(value) {
    crossPosition = Number(value) / 100;
    $('#crossfader').value = value;
    if (!audioContext) return;
    // Equal-power curve: constant perceived loudness through the center.
    decks.a.cross.gain.setTargetAtTime(Math.cos(crossPosition * Math.PI / 2), audioContext.currentTime, 0.015);
    decks.b.cross.gain.setTargetAtTime(Math.sin(crossPosition * Math.PI / 2), audioContext.currentTime, 0.015);
  }

  function setPitch(id, value) {
    const deck = decks[id];
    deck.pitch = Number(value);
    const rate = 1 + deck.pitch / 100;
    deck.audio.playbackRate = rate;
    deck.bpm = deck.baseBpm * rate;
    $(`#pitch-label-${id}`).textContent = `${deck.pitch >= 0 ? '+' : ''}${deck.pitch.toFixed(1)}%`;
    $(`#pitch-read-${id}`).textContent = `${deck.pitch >= 0 ? '+' : ''}${deck.pitch.toFixed(1)}%`;
    $(`#bpm-read-${id}`).textContent = deck.bpm.toFixed(1);
    updatePhase();
  }

  function attachTrack(id, url, details) {
    ensureAudio();
    const deck = decks[id];
    if (deck.objectUrl && deck.objectUrl.startsWith('blob:')) URL.revokeObjectURL(deck.objectUrl);
    deck.objectUrl = url;
    deck.audio.pause();
    deck.audio.src = url;
    deck.audio.loop = Boolean(details.loop);
    deck.trackName = details.name;
    deck.artist = details.artist || (details.demo ? 'DJ Lab · demo generativa' : 'Archivo local · solo este dispositivo');
    deck.demo = Boolean(details.demo);
    deck.baseBpm = Number(details.bpm) || (id === 'a' ? 120 : 124);
    deck.cuePoint = 0;
    setPitch(id, deck.pitch);
    $(`#track-${id}`).textContent = deck.trackName;
    $(`#artist-${id}`).textContent = deck.artist;
    $(`#wave-title-${id}`).textContent = deck.trackName.toUpperCase();
    setStatus('AUDIO PREPARADO');
    addToLibrary({ ...details, name: deck.trackName, bpm: deck.baseBpm, source: details.demo ? 'Demo' : 'Local' });
    updateTransport(id);
  }

  function addToLibrary(track) {
    const existing = library.findIndex(item => item.name === track.name && item.source === track.source);
    const entry = {
      id: track.id || `${Date.now()}-${Math.random().toString(36).slice(2, 7)}`,
      name: track.name,
      artist: track.artist || (track.demo ? 'DJ Lab' : 'Audio local'),
      bpm: Number(track.bpm) || null,
      duration: Number(track.duration) || (track.demo ? 60 / (Number(track.bpm) || 120) * 16 : 0),
      source: track.source || (track.demo ? 'Demo' : 'Local'),
      kind: track.demo ? 'demo' : 'local'
    };
    if (existing >= 0) library[existing] = entry; else library.unshift(entry);
    persistLibrary();
    renderLibrary();
  }

  function makeDemoWav(bpm, seed) {
    const sampleRate = 22050;
    const beat = 60 / bpm;
    const beatCount = 16;
    const length = Math.ceil(sampleRate * beat * beatCount);
    const samples = new Float32Array(length);
    let state = seed >>> 0;
    const random = () => { state = (state * 1664525 + 1013904223) >>> 0; return state / 4294967296; };
    for (let b = 0; b < beatCount; b++) {
      const start = Math.floor(b * beat * sampleRate);
      const kickLength = Math.floor(sampleRate * 0.24);
      for (let i = 0; i < kickLength && start + i < length; i++) {
        const t = i / sampleRate;
        const env = Math.exp(-t * 17);
        const freq = 43 + 75 * Math.exp(-t * 28);
        samples[start + i] += Math.sin(2 * Math.PI * freq * t) * env * 0.78;
      }
      if (b % 4 === 1 || b % 4 === 3) {
        const clapStart = start + Math.floor(sampleRate * beat * 0.12);
        for (let i = 0; i < sampleRate * 0.15 && clapStart + i < length; i++) {
          const t = i / sampleRate;
          samples[clapStart + i] += (random() * 2 - 1) * Math.exp(-t * 24) * 0.17;
        }
      }
      const hatStart = start + Math.floor(sampleRate * beat * 0.5);
      for (let i = 0; i < sampleRate * 0.045 && hatStart + i < length; i++) {
        const t = i / sampleRate;
