15:   function loadSavedLibrary() {
16:     try {
17:       const value = JSON.parse(localStorage.getItem(STORAGE_KEY) || '[]');
18:       return Array.isArray(value) ? value.filter(item => item && typeof item.name === 'string').slice(0, 100) : [];
